package com.example.yourapp // замените на ваш пакетfun formatNumber(number: Int): String {    return when {        number < 1_000 -> number.toString()        number < 10_000 -> {            val thousands = number / 1_000            val hundreds = (number % 1_000) / 100            "${thousands}.${hundreds}K"        }        number < 1_000_000 -> {            val thousands = number / 1_000            "${thousands}K"        }        number < 10_000_000 -> {            val millions = number / 1_000_000            val hundredThousands = (number % 1_000_000) / 100_000            "${millions}.${hundredThousands}M"        }        else -> {            val millions = number / 1_000_000            "${millions}M"        }    }}